<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Test round not found.');}$stage=ucfirst((string)$round['round_type']);$types=$round['round_type']==='heats'?['judges'=>'Judges','competitors'=>'Competitors','scoring'=>'Scoring Status','callbacks'=>'Callback Reveal']:($round['round_type']==='semifinal'?['judges'=>'Judges','competitors'=>'Semifinal Competitors','scoring'=>'Scoring Status','finalists'=>'Finalists Reveal']:['judges'=>'Judges','competitors'=>'Finalists','scoring'=>'Scoring Status','results'=>'Final Ranking','winners'=>'Winner Reveal']);$formats=['16:9'=>'16:9 Landscape','9:16'=>'9:16 Portrait','4:3'=>'4:3 Standard','16:10'=>'16:10 Landscape','21:9'=>'21:9 Ultra-wide','32:9'=>'32:9 Super-wide','1:1'=>'1:1 Square','custom'=>'Custom Resolution'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Projection Control</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border-radius:15px}.test{letter-spacing:.1em}.settings{border-left:5px solid #ffc107}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">Test Live Screen Projector</span><a class="btn btn-light btn-sm" href="../scoring-tests/select-mode.php">⌂ Test Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold test">TEST MODE · NOTHING ON THIS SCREEN CAN PUBLISH OFFICIAL BDC RESULTS OR POINTS</div><h1 class="h2 mb-1"><?=e($round['event_name'])?></h1><div class="text-muted mb-4"><?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e($stage)?></div><div class="card settings shadow-sm mb-4"><div class="card-body"><h2 class="h5">Screen & Layout</h2><div class="row g-2"><div class="col-md-4"><select id="format" class="form-select"><?php foreach($formats as $v=>$l):?><option value="<?=e($v)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-3"><select id="density" class="form-select"><option value="maximum" selected>Maximum Density</option><option value="auto">Auto</option><option value="large">Large Cards</option></select></div><div class="col-md-2"><input id="cw" class="form-control" type="number" min="100" placeholder="Custom width"></div><div class="col-md-2"><input id="ch" class="form-control" type="number" min="100" placeholder="Custom height"></div></div></div></div><div class="row g-3"><?php foreach($types as $key=>$label):?><div class="col-md-6"><div class="card shadow-sm h-100"><div class="card-body"><h2 class="h5"><?=e($label)?></h2><p class="text-muted small">Same adaptive projection layout using isolated Test data.</p><button class="btn btn-danger open" data-type="<?=e($key)?>">Open Test Projection</button><?php if($key==='winners'):?><div class="d-flex flex-wrap gap-2 mt-3"><?php foreach([5,4,3,2,1] as $p):?><button class="btn btn-dark btn-sm open" data-type="winners" data-place="<?=$p?>">Reveal #<?=$p?></button><?php endforeach;?><button class="btn btn-warning btn-sm open" data-type="winners" data-place="all">Show All Top 5</button></div><?php endif;?></div></div></div><?php endforeach;?></div></main><script>function u(type,place=''){const q=new URLSearchParams({round_id:'<?=$roundId?>',type,format:document.querySelector('#format').value,density:document.querySelector('#density').value});const w=document.querySelector('#cw').value,h=document.querySelector('#ch').value;if(w)q.set('width',w);if(h)q.set('height',h);if(place)q.set('place',place);return 'test-projection.php?'+q.toString()}document.querySelectorAll('.open').forEach(b=>b.onclick=()=>window.open(u(b.dataset.type,b.dataset.place||''),'_blank'));</script></body></html>